/**
 * Exo Jacobi-1D driver: mirrors PolyBench/C jacobi-1d.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* Include the Exo-generated kernel header. */
#include "generated/jacobi-1d/jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


@proc
def kernel_jacobi_1d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # Jacobi-1D stencil:
    #   for each time step, do a sweep writing B from A,
    #   then a sweep writing A from B.
    # We require n > 2 so that accesses at i-1 and i+1 are in-bounds.
    assert n > 2

    for t in seq(0, tsteps):
        # First sweep: read A, write B.
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Second sweep: read B, write A.
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


# -------------------------
# Scheduling / optimization
# -------------------------
# We optimize the kernel for a modern multi-core x64 CPU as follows:
#   1. Parallelize both spatial loops over i.
#      Each iteration of the i-loops writes to a distinct element of
#      A or B and only reads neighbors from the other array, so there
#      are no cross-iteration dependencies in i. Exo’s effect analysis
#      verifies this and then lowers the loops to OpenMP parallel-for.
#   2. Run a simplification pass to clean up any minor IR artifacts.

p = kernel_jacobi_1d

# Parallelize the B-update loop.
i_loop0 = p.find_loop("i")          # first 'i' loop in the time-stepping loop
p = parallelize_loop(p, i_loop0)

# Parallelize the A-update loop.
i_loop1 = p.find_loop("i #1")       # second 'i' loop in the time-stepping loop
p = parallelize_loop(p, i_loop1)

# Optional cleanup/simplification (no semantic change).
p = simplify(p)

# Export the optimized procedure under the original name so that the
# generated C symbol remains `kernel_jacobi_1d`, matching the header.
kernel_jacobi_1d = p
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to 1D pointers. */
  kernel_jacobi_1d (/*ctxt=*/NULL,
                    tsteps, n,
                    (DATA_TYPE*)POLYBENCH_ARRAY(A),
                    (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
