from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Base Jacobi-1D kernel: identical math to the PolyBench reference.
# Two arrays A and B "ping-pong" between time steps; only interior
# points [1, n-2] are updated, boundaries are left unchanged.
@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # Need at least one interior point
    assert n > 2

    for t in seq(0, tsteps):
        # Phase 1: update B from A (time t -> intermediate)
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Phase 2: update A from B (intermediate -> time t+1)
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


