# ---- Optimize B-update loop:  for i in seq(1, n - 1) ----

# Tile the first spatial loop (B update) by 256 over i.
# This creates:
#   for i0_B in seq(...):
#       for i1_B in seq(0, 256):
#           ...
kernel_jacobi_1d = divide_loop(
    kernel_jacobi_1d,
    "i",                 # first 'i' loop: B update
    256,                 # tile size
    ("i0_B", "i1_B"),
    tail="guard",        # guard the last, possibly partial tile
